556	// TestResolveCLIRequestErrorReasons exercises how malformed requests are
557	// explained at the command boundary: broken JSON is a parse failure, a legal
558	// non-object document says the request must be an object, and a legal object
559	// with a wrong-typed field names the field and the received type. Every
560	// failure still exits non-zero, leaves stdout empty and emits one JSON error.
561	func TestResolveCLIRequestErrorReasons(t *testing.T) {
562		cases := []struct {
563			name      string
564			request   string
565			want      []string
566			forbidden []string
567		}{
568			{
569				name:      "syntactically broken JSON",
570				request:   `{"method":"GET",`,
571				want:      []string{"not valid JSON"},
572				forbidden: []string{"method", "target"},
573			},
574			{
575				name:      "top level array is legal JSON but the wrong shape",
576				request:   `["GET","/api"]`,
577				want:      []string{"must be a JSON object"},
578				forbidden: []string{"not valid JSON"},
579			},
580			{
581				name:      "top level null is legal JSON but the wrong shape",
582				request:   `null`,
583				want:      []string{"must be a JSON object"},
584				forbidden: []string{"not valid JSON"},
585			},
586			{
587				name:      "numeric method is a field type error",
588				request:   `{"method":42,"target":"/api"}`,
589				want:      []string{"method must be a string", "got a number"},
590				forbidden: []string{"not valid JSON"},
591			},
592			{
593				name:      "array target is a field type error",
594				request:   `{"method":"GET","target":[]}`,
595				want:      []string{"target must be a string", "got an array"},
596				forbidden: []string{"not valid JSON", "start with /"},
597			},
598			{
599				name:      "null method is a type error, not a missing method",
600				request:   `{"method":null,"target":"/api"}`,
601				want:      []string{"method must be a string", "got null"},
602				forbidden: []string{"method is required"},
603			},
604			{
605				name:      "both fields wrong report method regardless of key order",
606				request:   `{"target":[],"method":42}`,
607				want:      []string{"method must be a string"},
608				forbidden: []string{"target must be a string"},
609			},
610			{
611				name:      "empty string is content validated, not type checked",
612				request:   `{"method":"GET","target":"/api%2"}`,
613				want:      []string{"invalid percent escape"},
614				forbidden: []string{"must be a string"},
615			},
616		}
617		for _, tc := range cases {
618			t.Run(tc.name, func(t *testing.T) {
619				res := runResolveCLI(t, cliSuccessConfig, tc.request)
620				if res.exitCode == 0 {
621					t.Fatalf("exit code = 0, want non-zero")
622				}
623				if len(res.stdout) != 0 {
624					t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
625				}
626				var fail struct {
627					Code   string `json:"code"`
628					Reason string `json:"reason"`
629				}
630				decodeOneJSON(t, res.stderr, "stderr", &fail)
631				if fail.Code != "invalid_request" {
632					t.Fatalf("code = %q, want invalid_request", fail.Code)
633				}
634				for _, want := range tc.want {
635					if !strings.Contains(fail.Reason, want) {
636						t.Errorf("reason = %q, want substring %q", fail.Reason, want)
637					}
638				}
639				for _, bad := range tc.forbidden {
640					if strings.Contains(fail.Reason, bad) {
641						t.Errorf("reason = %q must not contain %q", fail.Reason, bad)
642					}
643				}
644			})
645		}
646	
647		// A bad config is reported before the request is even examined, so a
648		// broken config paired with a broken request still yields invalid_config.
649		badConfig := `{"routes":[{"id":"x","methods":"GET","pathPrefix":"/a","upstream":"http://h"}]}`
650		res := runResolveCLI(t, badConfig, `{not json`)
651		if res.exitCode == 0 || len(res.stdout) != 0 {
652			t.Fatalf("got exit %d stdout %q, want non-zero exit and empty stdout", res.exitCode, res.stdout)
653		}
654		var fail struct {
655			Code string `json:"code"`
656		}
657		decodeOneJSON(t, res.stderr, "stderr", &fail)
658		if fail.Code != "invalid_config" {
659			t.Fatalf("code = %q, want invalid_config to take priority", fail.Code)
660		}
661	}
