1348		     "upstream": "http://orders.internal",
1349		     "queryTransforms": [{"op": "remove", "name": "bad name"}]}
1350		  ]
1351		}`
1352		cases := []struct {
1353			name    string
1354			config  string
1355			request string
1356			want    string
1357		}{
1358			{
1359				name:    "json newline escape after a matching prefix",
1360				config:  cliSuccessConfig,
1361				request: `{"method":"GET","target":"/api/orders\n"}`,
1362				want:    "U+000A",
1363			},
1364			{
1365				name:    "json tab escape in the path",
1366				config:  cliSuccessConfig,
1367				request: `{"method":"GET","target":"/api/orders\t/x"}`,
1368				want:    "U+0009",
1369			},
1370			{
1371				name:    "json null escape in a parameter value",
1372				config:  cliSuccessConfig,
1373				request: `{"method":"GET","target":"/api?x=1\u0000"}`,
1374				want:    "U+0000",
1375			},
1376			{
1377				name:    "del character via unicode escape",
1378				config:  cliSuccessConfig,
1379				request: `{"method":"GET","target":"/api/x\u007f"}`,
1380				want:    "U+007F",
1381			},
1382			{
1383				name:    "literal space in a parameter name",
1384				config:  cliSuccessConfig,
1385				request: `{"method":"GET","target":"/api/orders?a b=1"}`,
1386				want:    "U+0020",
1387			},
1388			{
1389				name:    "remove rule cannot delete the parameter carrying the space",
1390				config:  removeConfig,
1391				request: `{"method":"GET","target":"/api/orders?bad name=1&keep=2"}`,
1392				want:    "U+0020",
1393			},
1394			{
1395				name:    "first offender is the earlier newline, not the later space",
1396				config:  cliSuccessConfig,
1397				request: `{"method":"GET","target":"/api/a\nb c"}`,
1398				want:    "U+000A",
1399			},
1400		}
1401		for _, tc := range cases {
1402			t.Run(tc.name, func(t *testing.T) {
1403				res := runResolveCLI(t, tc.config, tc.request)
1404				if res.exitCode == 0 {
1405					t.Fatalf("exit code = 0, want non-zero")
1406				}
1407				if len(res.stdout) != 0 {
1408					t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
1409				}
1410				var fail struct {
1411					Code   string `json:"code"`
1412					Reason string `json:"reason"`
1413				}
1414				decodeOneJSON(t, res.stderr, "stderr", &fail)
1415				if fail.Code != "invalid_request" {
1416					t.Fatalf("code = %q, want invalid_request", fail.Code)
1417				}
1418				for _, want := range []string{"target", tc.want} {
1419					if !strings.Contains(fail.Reason, want) {
1420						t.Errorf("reason = %q, want substring %q", fail.Reason, want)
1421					}
1422				}
1423			})
1424		}
1425	
1426		// Percent-encoded control bytes stay data: the request resolves and the
1427		// escapes reach upstreamURL byte for byte.
1428		encoded := assertResolveSuccess(t, runResolveCLI(t, cliSuccessConfig,
1429			`{"method":"GET","target":"/api/orders%20next?note=%0A%09"}`))
1430		if encoded.RouteID != "api" {
1431			t.Errorf("routeId = %q, want api (encoded space keeps the segment under /api)", encoded.RouteID)
1432		}
1433		if want := "http://api.internal/v1/orders%20next?note=%0A%09"; encoded.UpstreamURL != want {
1434			t.Errorf("upstreamURL = %q, want %q", encoded.UpstreamURL, want)
1435		}
1436	
1437		// Config validation still precedes request parsing: a bad config paired
1438		// with a newline target yields invalid_config, and stdout stays empty.
1439		badConfig := `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"ftp://h"}]}`
1440		res := runResolveCLI(t, badConfig, `{"method":"GET","target":"/a\n"}`)
1441		if res.exitCode == 0 || len(res.stdout) != 0 {
1442			t.Fatalf("got exit %d stdout %q, want non-zero exit and empty stdout", res.exitCode, res.stdout)
1443		}
1444		var fail struct {
1445			Code string `json:"code"`
1446		}
1447		decodeOneJSON(t, res.stderr, "stderr", &fail)
1448		if fail.Code != "invalid_config" {
1449			t.Fatalf("code = %q, want invalid_config to take priority", fail.Code)
1450		}
1451	}
1452	
1453	func TestResolveCLIRouteConflict(t *testing.T) {
1454		// alpha and zeta both concretely accept GET at the same /api prefix
1455		// with no longer prefix to win; the same-prefix wildcard route must not
1456		// appear among the final candidates.
